import React from 'react';
import '../assets/styles/Services.css'; // Optional styling
import webDevIcon from '../assets/images/webdev.png';
import backendIcon from '../assets/images/backend.png';
import databaseIcon from '../assets/images/database.png';
import testingIcon from '../assets/images/testing.png';
import financeIcon from '../assets/images/finance.png';

const Services = () => {
  return (
    <div className="services">
      <h1>My Services</h1>
      <div className="service-list">
        <div className="service-card">
          <img src={webDevIcon} alt="Web Development" />
          <h2>Web Development</h2>
          <p>Building responsive and modern websites using HTML, CSS, JavaScript, and React.</p>
        </div>
        <div className="service-card">
          <img src={backendIcon} alt="Back-End Programming" />
          <h2>Back-End Programming</h2>
          <p>Creating server-side logic with Python, C#, and Java to power dynamic applications.</p>
        </div>
        <div className="service-card">
          <img src={databaseIcon} alt="Database Management" />
          <h2>Database Management</h2>
          <p>Designing and managing SQL/MySQL databases for scalable applications.</p>
        </div>
        <div className="service-card">
          <img src={testingIcon} alt="Software Testing" />
          <h2>Software Testing & QA</h2>
          <p>Ensuring software quality through testing, debugging, and documentation.</p>
        </div>
        <div className="service-card">
          <img src={financeIcon} alt="Financial Data Analysis" />
          <h2>Financial Data Analysis</h2>
          <p>Analyzing financial data and building tools for reporting and decision-making.</p>
        </div>
      </div>
    </div>
  );
};

export default Services;
